import React, { useState, useEffect } from 'react';
import { Download, Mail, Github, Linkedin, Code, Database, Cloud, ChevronDown, Sparkles, Star, Zap } from 'lucide-react';

const Hero = () => {
  const [currentRole, setCurrentRole] = useState(0);
  const [mousePosition, setMousePosition] = useState({ x: 0, y: 0 });
  const [isTyping, setIsTyping] = useState(true);

  const roles = [
    { 
      title: "Full-Stack Developer", 
      icon: <Code size={20} />, 
      color: "from-blue-500 to-blue-600",
      description: "Building end-to-end solutions",
      skills: ["React", "Node.js", "MongoDB"]
    },
    { 
      title: "Data Analyst", 
      icon: <Database size={20} />, 
      color: "from-green-500 to-green-600",
      description: "Transforming data into insights",
      skills: ["Python", "Power BI", "SQL"]
    },
    { 
      title: "IT Officer", 
      icon: <Cloud size={20} />, 
      color: "from-purple-500 to-purple-600",
      description: "Managing digital infrastructure",
      skills: ["AWS", "DevOps", "Security"]
    }
  ];

  const achievements = [
    { icon: <Star className="w-4 h-4" />, text: "50+ Projects Delivered" },
    { icon: <Zap className="w-4 h-4" />, text: "5+ Years Experience" },
    { icon: <Sparkles className="w-4 h-4" />, text: "Ethiopia Based" }
  ];

  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentRole((prev) => (prev + 1) % roles.length);
      setIsTyping(true);
      setTimeout(() => setIsTyping(false), 500);
    }, 4000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    const handleMouseMove = (e) => {
      setMousePosition({ 
        x: (e.clientX / window.innerWidth) * 100,
        y: (e.clientY / window.innerHeight) * 100
      });
    };

    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  return (
    <section className="min-h-screen bg-gradient-to-br from-gray-50 via-white to-blue-50 relative overflow-hidden">
      {/* Enhanced background elements */}
      <div className="absolute inset-0 overflow-hidden">
        {/* Interactive gradient that follows mouse */}
        <div 
          className="absolute w-96 h-96 bg-gradient-to-r from-primary-200/40 to-accent-200/40 rounded-full filter blur-3xl transition-all duration-1000 ease-out"
          style={{
            left: `${mousePosition.x}%`,
            top: `${mousePosition.y}%`,
            transform: 'translate(-50%, -50%)'
          }}
        ></div>

        {/* Floating geometric shapes */}
        <div className="absolute top-20 left-20 w-32 h-32 bg-primary-100 rounded-full mix-blend-multiply filter blur-xl opacity-40 animate-float"></div>
        <div className="absolute -bottom-40 -left-40 w-80 h-80 bg-accent-100 rounded-full mix-blend-multiply filter blur-xl opacity-30 animate-float" style={{animationDelay: '2s'}}></div>
        <div className="absolute top-40 right-20 w-60 h-60 bg-purple-100 rounded-full mix-blend-multiply filter blur-xl opacity-30 animate-float" style={{animationDelay: '4s'}}></div>

        {/* Animated grid pattern */}
        <div className="absolute inset-0 opacity-5">
          <div className="grid grid-cols-12 gap-4 h-full">
            {Array.from({ length: 144 }).map((_, i) => (
              <div 
                key={i}
                className="bg-primary-500 rounded-full w-1 h-1 animate-pulse"
                style={{
                  animationDelay: `${i * 0.1}s`,
                  animationDuration: '3s'
                }}
              ></div>
            ))}
          </div>
        </div>
      </div>

      <div className="container-max section-padding relative z-10">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-center min-h-screen max-w-7xl mx-auto">

          {/* Left Content */}
          <div className="lg:col-span-7 space-y-8 text-center lg:text-left">
            {/* Enhanced Greeting with achievements */}
            <div className="animate-fade-in space-y-4">
              <div className="inline-flex items-center gap-2 px-4 py-2 bg-white/80 backdrop-blur-sm rounded-full shadow-lg border border-gray-200 text-gray-600 text-sm font-medium">
                <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></div>
                Available for opportunities
              </div>

              {/* Achievement badges */}
              <div className="flex flex-wrap gap-2 justify-center lg:justify-start">
                {achievements.map((achievement, index) => (
                  <div 
                    key={index}
                    className="inline-flex items-center gap-1 px-3 py-1 bg-white/60 backdrop-blur-sm rounded-full text-xs font-medium text-gray-600 border border-gray-200/50"
                    style={{animationDelay: `${0.1 + index * 0.1}s`}}
                  >
                    <span className="text-primary-500">{achievement.icon}</span>
                    {achievement.text}
                  </div>
                ))}
              </div>
            </div>

            {/* Enhanced Main Heading */}
            <div className="animate-slide-up" style={{animationDelay: '0.2s'}}>
              <div className="relative">
                <h1 className="text-5xl md:text-6xl lg:text-7xl font-bold text-gray-900 mb-6 font-poppins leading-tight">
                  Samuel
                  <br />
                  <span className="gradient-text relative">
                    Alemayehu
                    <div className="absolute -top-2 -right-2 w-4 h-4 bg-yellow-400 rounded-full animate-bounce opacity-80"></div>
                  </span>
                </h1>
                {/* Decorative line */}
                <div className="w-20 h-1 bg-gradient-to-r from-primary-500 to-accent-500 rounded-full mx-auto lg:mx-0"></div>
              </div>
            </div>


            {/* Enhanced Description */}
            <div className="animate-slide-up" style={{animationDelay: '0.6s'}}>
              <div className="relative">
                <p className="text-lg text-gray-700 leading-relaxed mx-auto lg:mx-0">
                  Passionate about leveraging technology to solve complex problems and drive innovation. 
                  With expertise spanning full-stack development, data analysis, and IT operations, 
                  I create digital solutions that make a meaningful impact.
                </p>
                {/* Quote decoration */}
                <div className="absolute -left-4 top-0 text-6xl text-primary-200 font-serif leading-none">"</div>
              </div>
            </div>

            {/* Enhanced Action Buttons */}
            <div className="flex flex-col sm:flex-row gap-4 justify-center lg:justify-start animate-slide-up" style={{animationDelay: '0.8s'}}>
              <button className="group relative bg-gradient-to-r from-primary-600 to-primary-700 hover:from-primary-700 hover:to-primary-800 text-white px-8 py-4 rounded-xl font-medium transition-all duration-300 transform hover:scale-105 hover:shadow-2xl flex items-center justify-center gap-2 overflow-hidden">
                <div className="absolute inset-0 bg-gradient-to-r from-white/0 via-white/20 to-white/0 -skew-x-12 -translate-x-full group-hover:translate-x-full transition-transform duration-1000"></div>
                <Download size={20} className="group-hover:animate-bounce relative z-10" />
                <span className="relative z-10">Download CV</span>
              </button>

              <button className="group relative bg-white/80 backdrop-blur-sm hover:bg-white text-primary-600 px-8 py-4 rounded-xl font-medium border-2 border-primary-600 transition-all duration-300 transform hover:scale-105 hover:shadow-2xl flex items-center justify-center gap-2 overflow-hidden">
                <div className="absolute inset-0 bg-gradient-to-r from-primary-50 to-accent-50 opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
                <Mail size={20} className="group-hover:animate-pulse relative z-10" />
                <span className="relative z-10">Contact Me</span>
              </button>
            </div>

            {/* Enhanced Social Links */}
            <div className="flex justify-center lg:justify-start gap-4 animate-slide-up" style={{animationDelay: '1s'}}>
              {[
                { icon: <Github size={20} />, href: "https://github.com/samuelalemayehu", label: "GitHub", color: "hover:bg-gray-900 hover:text-white" },
                { icon: <Linkedin size={20} />, href: "https://linkedin.com/in/samuelalemayehu", label: "LinkedIn", color: "hover:bg-blue-600 hover:text-white" },
                { icon: <Mail size={20} />, href: "mailto:samuel.alemayehu@email.com", label: "Email", color: "hover:bg-red-500 hover:text-white" }
              ].map((social, index) => (
                <a
                  key={index}
                  href={social.href}
                  target="_blank"
                  rel="noopener noreferrer"
                  className={`group w-12 h-12 bg-white/80 backdrop-blur-sm rounded-xl shadow-lg flex items-center justify-center text-gray-700 hover:shadow-2xl transition-all duration-300 transform hover:scale-110 border border-gray-200/50 ${social.color}`}
                  aria-label={social.label}
                >
                  <div className="transform group-hover:rotate-12 transition-transform duration-300">
                    {social.icon}
                  </div>
                </a>
              ))}
            </div>
          </div>

          {/* Interactive Dashboard */}
          <div className="lg:col-span-5 flex justify-center lg:justify-end">
            <div className="relative animate-fade-in w-full max-w-md" style={{animationDelay: '1.2s'}}>

              {/* Modern Dashboard Container */}
              <div className="bg-white/80 backdrop-blur-xl rounded-3xl p-6 shadow-2xl border border-gray-200/50 space-y-6">

                {/* Header with Live Status */}
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className="w-12 h-12 bg-gradient-to-br from-primary-500 to-accent-500 rounded-xl flex items-center justify-center text-white font-bold text-lg shadow-lg">
                      SA
                    </div>
                    <div>
                      <h3 className="font-semibold text-gray-900">Samuel Alemayehu</h3>
                      <div className="flex items-center gap-2 text-sm text-gray-600">
                        <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></div>
                        <span>Available for work</span>
                      </div>
                    </div>
                  </div>
                  <div className="text-2xl">🇪🇹</div>
                </div>

                {/* Interactive Metrics Grid */}
                <div className="grid grid-cols-2 gap-4">
                  <div className="bg-gradient-to-br from-blue-50 to-blue-100 rounded-2xl p-4 border border-blue-200/50 hover:shadow-lg transition-all duration-300 group cursor-pointer">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 bg-blue-500 rounded-xl flex items-center justify-center text-white">
                        <Code size={20} />
                      </div>
                      <div>
                        <div className="text-2xl font-bold text-blue-700 group-hover:scale-110 transition-transform">50+</div>
                        <div className="text-xs text-blue-600">Projects</div>
                      </div>
                    </div>
                  </div>

                  <div className="bg-gradient-to-br from-green-50 to-green-100 rounded-2xl p-4 border border-green-200/50 hover:shadow-lg transition-all duration-300 group cursor-pointer">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 bg-green-500 rounded-xl flex items-center justify-center text-white">
                        <Database size={20} />
                      </div>
                      <div>
                        <div className="text-2xl font-bold text-green-700 group-hover:scale-110 transition-transform">5+</div>
                        <div className="text-xs text-green-600">Years Exp</div>
                      </div>
                    </div>
                  </div>

                  <div className="bg-gradient-to-br from-purple-50 to-purple-100 rounded-2xl p-4 border border-purple-200/50 hover:shadow-lg transition-all duration-300 group cursor-pointer">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 bg-purple-500 rounded-xl flex items-center justify-center text-white">
                        <Cloud size={20} />
                      </div>
                      <div>
                        <div className="text-2xl font-bold text-purple-700 group-hover:scale-110 transition-transform">3</div>
                        <div className="text-xs text-purple-600">Roles</div>
                      </div>
                    </div>
                  </div>

                  <div className="bg-gradient-to-br from-orange-50 to-orange-100 rounded-2xl p-4 border border-orange-200/50 hover:shadow-lg transition-all duration-300 group cursor-pointer">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 bg-orange-500 rounded-xl flex items-center justify-center text-white">
                        <Star size={20} />
                      </div>
                      <div>
                        <div className="text-2xl font-bold text-orange-700 group-hover:scale-110 transition-transform">92%</div>
                        <div className="text-xs text-orange-600">Success Rate</div>
                      </div>
                    </div>
                  </div>
                </div>

                {/* Tech Stack Radar */}
                <div className="space-y-4">
                  <h4 className="text-sm font-semibold text-gray-900 flex items-center gap-2">
                    <Zap size={16} className="text-yellow-500" />
                    Tech Stack
                  </h4>

                  <div className="space-y-3">
                    {[
                      { name: 'Frontend', level: 95, color: 'bg-blue-500' },
                      { name: 'Backend', level: 90, color: 'bg-green-500' },
                      { name: 'Database', level: 85, color: 'bg-purple-500' },
                      { name: 'DevOps', level: 80, color: 'bg-orange-500' }
                    ].map((skill, index) => (
                      <div key={index} className="space-y-1">
                        <div className="flex justify-between text-xs">
                          <span className="font-medium text-gray-700">{skill.name}</span>
                          <span className="text-gray-500">{skill.level}%</span>
                        </div>
                        <div className="w-full bg-gray-200 rounded-full h-2">
                          <div 
                            className={`${skill.color} h-2 rounded-full transition-all duration-1000 ease-out`}
                            style={{ width: `${skill.level}%`, animationDelay: `${index * 0.2}s` }}
                          ></div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>

                {/* Quick Actions */}
                <div className="flex gap-3">
                  <button className="flex-1 bg-gradient-to-r from-primary-500 to-primary-600 text-white py-3 px-4 rounded-xl text-sm font-medium hover:shadow-lg transition-all duration-300 transform hover:scale-105">
                    View Work
                  </button>
                  <button className="flex-1 bg-gray-100 hover:bg-gray-200 text-gray-700 py-3 px-4 rounded-xl text-sm font-medium transition-all duration-300 transform hover:scale-105">
                    Contact
                  </button>
                </div>
              </div>

              {/* Floating Tech Icons */}
              <div className="absolute -top-4 -right-4 w-8 h-8 bg-gradient-to-r from-blue-500 to-purple-500 rounded-lg opacity-20 animate-float flex items-center justify-center text-white text-xs">
                ⚛️
              </div>
